+    const initialRequests = requests.length;
+    const refreshedPage = page.waitForResponse(
+        (response) =>
+            new URL(response.url()).pathname === "/api/runs/summary" &&
+            new URL(response.url()).searchParams.get("offset") === "200",
+    );
